let cx, cy;
let num = 16;
let test, w, a;
let inkArray = [];
let prevPos;
let maxSize = [];
let opacityArray = []; // New array for opacity

function setup() {
  // Calculate a canvas size that fits the screen while maintaining a 1080:1920 ratio
  let canvasHeight = window.innerHeight * 0.8;
  let canvasWidth = (1080 / 1920) * canvasHeight;

  createCanvas(canvasWidth, canvasHeight);
  background(20, 15, 10); // Sets a solid black background
  cx = width / 2;
  cy = height / 2;

  for (let i = 0; i < num; i++) {
    inkArray[i] = createVector(random(width), 0);a
    maxSize[i] = random(height);
    opacityArray[i] = random(50, 255); // Initialize opacity for each drip
  }
}

function draw() {
  // We do not clear the background here, so the previous lines will remain.

  for (let i = 0; i < num; i++) {
    // Save the previous position
    prevPos = inkArray[i].copy();

    // Update the position
    inkArray[i].x += random(-0.5, 0.5);

    inkArray[i].y += random(4);
    w = abs(maxSize[i] / (inkArray[i].y + 18));
    a = map(inkArray[i].y, maxSize[i], 0, 0, 200);

    strokeWeight(w + 3);
    stroke(255, 180, 100, opacityArray[i]); // Use the individual opacity value

    if (inkArray[i].y < maxSize[i]) {
      line(prevPos.x, prevPos.y, inkArray[i].x, inkArray[i].y);
    } else {
      // When the drip resets, also reset its opacity
      inkArray[i] = createVector(random(-100, 100) + cx, 0);
      maxSize[i] = random(height);
      opacityArray[i] = random(50, 255); // Reset opacity
    }
  }
}

